import React from 'react'
import Image from 'next/image'
import { image } from '../../app/store/image.png'
const AccountToggle = () => {
  return (
    <div className='border-b mb-4 mt-2 pb-4 border-stone-300'>
      <button className='flex p-0.5 hover:bg-stone-200 rounded transition-color relative gap-2 w-full item-center'>
        <Image src="" alt='IMAGE' width={32} height={32} className='rounded-full' />
      </button>
    </div>
  )
}

export default AccountToggle
